import{d as p,C as t,o as d,c as h,a3 as s,E as e,j as n,a as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第四章","description":"《正易心法》第四章——《易》道不传，乃有周孔：上古卦画明则道行，后世卦画不明则道晦；学者执辞忘象，只作八字说，此谓之买椟还珠。","frontmatter":{"title":"正易心法·第四章","description":"《正易心法》第四章——《易》道不传，乃有周孔：上古卦画明则道行，后世卦画不明则道晦；学者执辞忘象，只作八字说，此谓之买椟还珠。","category":"guide","aliases":["正易心法第四章","易道不传乃有周孔","买椟还珠"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-04.md","filePath":"yijing/zheng-yi-xin-fa/chapter-04.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-04.md"},x=p({...c,setup(u){const i=[{id:"z4-01",label:"一、道不传乃有周孔",showLabel:!0,sentences:[["《易》道",{text:"不传",glossary:"buzhuan"},"，乃有周、孔。周、孔",{text:"孤行",glossary:"guxing"},"，《易》道",{text:"复晦",glossary:"fuhui"},"。"]],note:["《易》道失传，才不得已有了周文王和孔子的文字；而周孔之辞孤立地流行，《易》道反而再度晦暗。「不传」指卦画之学失传，不是文字失传——文字恰恰因为卦画失传才有了用武之地。"]},{id:"z4-02",label:"二、卦画明则道行",showLabel:!0,sentences:[["上古卦画明，《易》道行。后世卦画不明，《易》道不传。"]],note:["上古时代卦画清明，《易》道畅行于天下；后世卦画之学不再明了，《易》道于是失传。（这一句是全书的历史判断：道之明晦，全系于卦画之明不明，与文字多寡无关。）"]},{id:"z4-03",label:"三、不得已而有辞",showLabel:!0,sentences:[["圣人于是",{text:"不得已",glossary:"budeyi"},"而",{text:"有辞",glossary:"youci"},"。"]],note:["圣人（文王、孔子）迫不得已，才立下文字辞句。「不得已」三字是极微妙的定性：麻衣并不否定文王、孔子，而是说他们知道卦画才是本体，只因面对「卦画不明」的时代，不得不用文字来补救——错不在圣人，错在后人把补救手段当成了目的。"]},{id:"z4-04",label:"四、学者浅识",showLabel:!0,sentences:[["学者",{text:"浅识",glossary:"qianshi"},"，一著其辞，便谓《易》止于是，而周、孔遂自孤行。"]],note:["然而后世学者见识浅薄，一旦接触到这些文辞，便以为《易》不过如此，于是周孔之辞便孤立地流传。（「一著其辞」的「著」是接触、着眼于；辞本为「药方」，后人却把药方当饭吃。）"]},{id:"z4-05",label:"五、只作八字说",showLabel:!0,sentences:[["更不知有卦画",{text:"微旨",glossary:"weizhi"},"，只作",{text:"八字说",glossary:"baziShuo"},"。"]],note:["更不知道卦画还有精微的旨意，只用几个字来解说卦义。（「八字」指「乾健、坤顺、震动、巽入、坎陷、离丽、艮止、兑说」这八个字，出自《说卦传》。麻衣的批评是：这八个字是**结果**，卦画结构才是**原因**——乾为什么健？因为六爻皆阳；坎为什么陷？因为一阳陷于二阴之中。执果忘因，是为浅识。）"]},{id:"z4-06",label:"六、买椟还珠",showLabel:!0,sentences:[["此谓之",{text:"买椟还珠",glossary:"maiduHuanzhu"},"，由汉以来皆然，《易》道",{text:"胡为",glossary:"huwei"},"而不晦也？"]],note:["这就叫做「买椟还珠」——自汉代以来都是如此，《易》道怎么能不晦暗呢？（典出《韩非子》：买下装珠的木匣，却把珍珠退还。此处「椟」是周孔文辞，「珠」是卦画微旨。）"]}],o=[{id:"buzhuan",term:"不传",pinyin:"bù chuán",meaning:"不能流传、失传。此处指卦画之学失传，不是文字失传。"},{id:"guxing",term:"孤行",pinyin:"gū xíng",meaning:"单独运行、孤立存在。周孔之辞脱离卦画而独立流传。"},{id:"fuhui",term:"复晦",pinyin:"fù huì",meaning:"再度晦暗。晦是隐没不明，复是再次。"},{id:"budeyi",term:"不得已",pinyin:"bù dé yǐ",meaning:"迫不得已。强调文字是补救手段，非本意。"},{id:"youci",term:"有辞",pinyin:"yǒu cí",meaning:"立下文字辞句。指文王卦辞爻辞、孔子十翼。"},{id:"qianshi",term:"浅识",pinyin:"qiǎn shí",meaning:"见识浅薄。批评后世学者不识卦画本旨。"},{id:"weizhi",term:"微旨",pinyin:"wēi zhǐ",meaning:"精微的旨意。指卦画深层含义，非表面文字可达。"},{id:"baziShuo",term:"八字说",pinyin:"bā zì shuō",meaning:"只作八个字解释。指仅以「乾健坤顺」等简单标签论卦（语出《说卦传》），是执果忘因。"},{id:"maiduHuanzhu",term:"买椟还珠",pinyin:"mǎi dú huán zhū",meaning:"《韩非子》寓言：买下装珠的木匣，却退还珍珠。喻舍本逐末。此处「椟」是周孔文辞，「珠」是卦画微旨。"},{id:"huwei",term:"胡为",pinyin:"hú wéi",meaning:"为何、怎么。反问语气。"}];return(b,a)=>{const l=t("DaoTextReading"),r=t("DaoKeywordCards");return d(),h("div",null,[a[0]||(a[0]=s(`<h1 id="正易心法·第四章" tabindex="-1">正易心法·第四章 <a class="header-anchor" href="#正易心法·第四章" aria-label="Permalink to &quot;正易心法·第四章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是<strong>前三章的历史化论证</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>论域</th><th>要点</th></tr></thead><tbody><tr><td>第一章</td><td>认识论</td><td>落处在卦画</td></tr><tr><td>第二章</td><td>本体论</td><td>卦画是自然节律</td></tr><tr><td>第三章</td><td>历史论</td><td>羲皇本无文字</td></tr><tr><td><strong>第四章</strong></td><td><strong>批判论</strong></td><td><strong>文字如何反客为主，遮蔽了卦画</strong></td></tr></tbody></table><p>四章合起来，构成《正易心法》的完整理论地基：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为什么要读这本书？</span></span>
<span class="line"><span>    ↓ 因为《易》道已晦</span></span>
<span class="line"><span>晦在哪里？晦在执辞忘象</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>象是什么？是卦画自然节律</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>怎么读象？知落处，嘿观</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>所以《正易心法》要做的事：重新指向卦画，绕过文字的遮蔽</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「不得已」三个字的分量</strong>——这是对文王、孔子的定性：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>圣人之辞 = 药方（针对「卦画不明」这个病）</span></span>
<span class="line"><span>后世学者 = 把药方当饭吃，忘了病已经不同了</span></span>
<span class="line"><span>结果     = 药方孤行，病情（晦暗）反而加重</span></span></code></pre></div><p><strong>「只作八字说」是什么意思？</strong> 这八个字是《说卦传》对八卦的义理概括：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾：健  坤：顺  震：动  巽：入  坎：陷  离：丽  艮：止  兑：说</span></span></code></pre></div><p>麻衣的批评是：<strong>这八个字是结果，卦画结构才是原因</strong>——乾为什么健？因为六爻皆阳，纯阳不息；坎为什么陷？因为一阳陷于二阴之中。<strong>执果忘因，是为浅识。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读「上古卦画明 → 后世卦画不明」这条历史线；</li><li>再品「不得已」三字——<strong>麻衣批的是后人，不是圣人</strong>；</li><li>最后看「买椟还珠」的对应：椟＝周孔文辞，珠＝卦画微旨。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>不传</strong>：卦画之学失传（非文字失传）。</li><li><strong>孤行 / 复晦</strong>：辞脱离象而成独立传统，道反而更晦。</li><li><strong>不得已而有辞</strong>：文字是补救，不是本体。</li><li><strong>只作八字说</strong>：以「乾健坤顺」代卦画，执果忘因。</li><li><strong>买椟还珠</strong>：椟是辞，珠是象；汉以来皆然。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,17)),e(l,{colophon:"乃有周孔 · 周孔孤行 · 不得已而有辞 · 买椟还珠",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[g("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"不得已",pinyin:["bù","dé","yǐ"],meaning:"迫不得已。强调文字是补救手段，非本意——麻衣批的是执辞忘象的后人，不是文王、孔子。"},{term:"八字说",pinyin:["bā","zì"],meaning:"乾健、坤顺、震动、巽入、坎陷、离丽、艮止、兑说八个字（出自《说卦传》）。麻衣说它是「果」不是「因」。"},{term:"买椟还珠",pinyin:["mǎi","dú","huán","zhū"],meaning:"《韩非子》寓言：买下装珠的木匣，却退还珍珠。「椟」是周孔文辞，「珠」是卦画微旨。"},{term:"微旨",pinyin:["wēi","zhǐ"],meaning:"精微的旨意。指卦画深层含义，非表面文字可达。"}]}),a[3]||(a[3]=s(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>前三章的历史化论证</strong>，也是全书最直接的批评一章：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一章：落处在卦画（认识论）</span></span>
<span class="line"><span>第二章：卦画是自然节律（本体论）</span></span>
<span class="line"><span>第三章：羲皇本无文字（历史论）</span></span>
<span class="line"><span>第四章：文字如何反客为主，遮蔽了卦画（批判论）</span></span></code></pre></div><p>四章合起来给出「<strong>为什么要读这本书</strong>」的答案：<strong>因为《易》道已晦，晦在执辞忘象。</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「不得已」三字极精妙</strong>——圣人立辞是「药方」：</p><table tabindex="0"><thead><tr><th>项</th><th>对应</th></tr></thead><tbody><tr><td>药方</td><td>圣人之辞</td></tr><tr><td>病</td><td>卦画不明</td></tr><tr><td>后人之失</td><td>把药方当饭吃</td></tr></tbody></table><p>**「只作八字说」**指向《说卦传》的八个字：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾：健  坤：顺  震：动  巽：入  坎：陷  离：丽  艮：止  兑：说</span></span></code></pre></div><p><strong>字是结果，象是原因；执果忘因，是为浅识。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>分清「<strong>批后人 ≠ 批圣人</strong>」这一点，否则容易读成反孔；</li><li>把「椟」与「珠」的对应关系记住；</li><li>带着一个问题往下读：<strong>汉代易学到底做了什么，让麻衣如此不满？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《易》道失传，才不得已有了周文王和孔子的文字。周孔之辞孤立流行，《易》道反而再度晦暗。</p><p>上古时代卦画清明，《易》道畅行于天下。后世卦画之学不再明了，《易》道于是失传。圣人迫不得已，才立下文字辞句。</p><p>然而后世学者见识浅薄，一旦接触到这些文辞，便以为《易》不过如此，于是周孔之辞便孤立地流行。更不知道卦画还有精微的旨意，只用几个字来解说卦义。</p><p>这就叫做「买椟还珠」——自汉代以来皆是如此，《易》道怎么能不晦暗呢？</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第四章把前三章的地基转成了一句质问——<strong>「《易》道胡为而不晦也？」</strong> 晦不在文字太多，而在<strong>读者把文字当成了全部</strong>。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「不得已」</strong>——这个词很厚道：<strong>麻衣批的是「执辞忘象」的人，不是立辞的圣人。</strong> 我读这句话时，有没有误以为他在反孔？</li><li><strong>「药方」的比喻</strong>——圣人之辞是对症的药；病好了还照方吃，就成了新病。<strong>我手上有没有这种「照方吃」的习惯？</strong></li><li><strong>「只作八字说」</strong>——乾健、坤顺……这八个字是《说卦传》给的<strong>结果</strong>。麻衣要我把结果还原成原因（六爻皆阳所以健）。<strong>这是不是也是一种「找落处」？</strong></li><li><strong>「由汉以来皆然」</strong>——麻衣把晦暗的起点定在汉代。<strong>为什么是汉？</strong> 这里埋着下一层（汉代训诂学与象数繁化）。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>陈抟之后，邵雍的先天易学、朱熹的本义，算不算对「买椟还珠」的纠偏？</strong> 他们有没有真正找回卦画的落处？——这一问，等读完全书再回答会更有底气。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 落处在卦画</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-02">第二章 · 六画之设</a> — 卦画是自然节律</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-03">第三章 · 卦象视人</a> — 羲皇本无文字</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「乾健坤顺」八字所出，本章恰说它是「果」不是「因」</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「圣人设卦观象，系辞焉而明吉凶」：孔子自陈的「降级」，正是本章批评的起点</li></ul>`,24))])}}});export{y as __pageData,x as default};
